      const otherWriter=!!remote.writer&&(remote.writer.verified!==true||remote.writer.actorId!==accountId()||remote.writer.deviceId!==localDeviceId());const remoteAdditions=otherWriter&&base?C.compare(remote.payload,base).filter(d=>d.local!==undefined&&d.remote===undefined&&!['recordOrder','collectionOrder'].includes(d.kind)):[];let changes,journal=[];
